// Extract parameters and determine dry-run mode
const input = $input.first()?.json || {};
const isDryRun = input.dryRun === true || input.body?.dryRun === true || false;

return [{
  json: {
    dryRun: isDryRun,
    spreadsheetId: input.spreadsheetId || $env.GOOGLE_SHEETS_SPREADSHEET_ID || '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
    sheetName: 'AquaCart_Catalog_Social',
    instagramAccountId: $env.INSTAGRAM_BUSINESS_ACCOUNT_ID || '17841400000000000',
    executionTimestamp: new Date().toISOString()
  }
}];

// Fallback product catalog if Google Sheets returns empty or offline
const fallbackCatalog = [
  {
    rowNumber: 2,
    Product_ID: 'prod-ro-01',
    Title: 'AquaPure Alkaline RO+UV+UF+Copper 12L',
    Category: 'Domestic RO Purifiers',
    Price_Retail: '14999',
    Price_Wholesale: '9500',
    Key_Features: 'Active Copper infusion, 12L capacity, 100% natural mineral balance, TDS reduction up to 2000 ppm',
    USP: 'Drink natural antioxidant alkaline water with 8.5+ pH daily for boosted digestion and immunity.',
    Status_Posted: 'NO',
    Posted_Date: '',
    Instagram_Media_ID: ''
  },
  {
    rowNumber: 3,
    Product_ID: 'prod-ro-02',
    Title: 'HydroShield Under-Sink Compact RO System',
    Category: 'Under-Sink Purifiers',
    Price_Retail: '17999',
    Price_Wholesale: '12900',
    Key_Features: 'Sleek under-counter design, brushed nickel faucet, 15 LPH flow rate, smart leak detector',
    USP: 'Zero countertop clutter. Modern European aesthetics with state-of-the-art 7-stage purification.',
    Status_Posted: 'NO',
    Posted_Date: '',
    Instagram_Media_ID: ''
  },
  {
    rowNumber: 4,
    Product_ID: 'prod-comm-01',
    Title: 'AquaCommercial 50 LPH Stainless Steel RO Plant',
    Category: 'Commercial & Industrial',
    Price_Retail: '34999',
    Price_Wholesale: '25500',
    Key_Features: 'Full SS-304 frame, dual pressure gauges, low maintenance commercial booster pump',
    USP: 'Reliable 500 liters/day pure water output for offices, restaurants, schools, and hospitals.',
    Status_Posted: 'NO',
    Posted_Date: '',
    Instagram_Media_ID: ''
  },
  {
    rowNumber: 5,
    Product_ID: 'prod-filter-01',
    Title: 'Complete 5-Stage Purifier Filter & Membrane Kit',
    Category: 'Filters & Spares',
    Price_Retail: '1799',
    Price_Wholesale: '1100',
    Key_Features: 'Sediment, Activated Carbon, Block Carbon, 80 GPD Membrane, Post Carbon remineralizer',
    USP: 'Factory certified OEM filters. Prevent costly motor damage by replacing filters on schedule.',
    Status_Posted: 'NO',
    Posted_Date: '',
    Instagram_Media_ID: ''
  }
];

const items = $input.all();
let products = [];

// If sheets returned items, use them; otherwise use fallback
if (items.length > 0 && items[0].json && items[0].json.Product_ID) {
  products = items.map((item, index) => ({
    ...item.json,
    rowNumber: item.json.rowNumber || (index + 2)
  }));
} else {
  products = fallbackCatalog;
}

// CRITICAL IDEMPOTENCY FILTER: Select only unposted products to prevent duplicate posts
const unposted = products.filter(p => !p.Status_Posted || p.Status_Posted.toString().toUpperCase() !== 'YES');

if (unposted.length === 0) {
  // All products have been posted
  return [{
    json: {
      hasUnpostedProduct: false,
      message: 'All catalog products have already been posted to Instagram. Queue complete.',
      timestamp: new Date().toISOString()
    }
  }];
}

// Select the first unposted product
const selected = unposted[0];
const config = $('Initialize Config & Dry-Run Mode').first().json;

return [{
  json: {
    hasUnpostedProduct: true,
    product: selected,
    dryRun: config.dryRun,
    spreadsheetId: config.spreadsheetId,
    sheetName: config.sheetName,
    instagramAccountId: config.instagramAccountId
  }
}];

